window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["rnn"]={"title":"循环神经网络 RNN：把历史压进一个不断更新的状态","subtitle":"从共享递推、时间展开与 BPTT，到梯度连乘、LSTM 门控、教师强制和流式部署。","thesis":"RNN 在每个时间步复用同一组参数，以隐藏状态压缩此前序列。它天然适合流式输入、状态小且单步成本固定；代价是<b>时间步难并行、历史有损压缩、梯度沿时间反复连乘</b>，因此长距离信用分配和精确回看都困难。","quality":{"contractVersion":2,"examples":[{"section":2,"evidence":{"setup":"沿用上一节的一维输入 x=[1,0,2]","rule":"Wₕ=0.5","steps":"h₃=0.5×0.5+2=2.25","interpretation":"早期信息按距离指数衰减"}}],"formulas":[{"id":"rnn-recurrence","section":1,"formulaIndex":1,"symbols":[{"name":"h","meaning":"更新前后的隐藏状态","evidence":"hₜ₋₁ 与 hₜ 是更新前后的隐藏状态"},{"name":"t","meaning":"序列当前时间步编号","evidence":"t 是时间步"},{"name":"φ","meaning":"把状态预激活转换为新状态的激活函数","evidence":"φ 是状态激活"},{"name":"W","meaning":"状态、输入或输出使用的共享权重","evidence":"Wₕ 变换旧状态"},{"name":"x","meaning":"当前时间步输入","evidence":"xₜ 是当前输入"},{"name":"b","meaning":"状态递推使用的偏置","evidence":"b 是偏置"},{"name":"y","meaning":"由当前状态产生的时间步输出","evidence":"当前输出 yₜ"},{"name":"g","meaning":"把隐藏状态转换为任务输出的函数","evidence":"g 把状态变成当前输出"}]},{"id":"rnn-worked-recurrence","section":2,"formulaIndex":1,"symbols":[{"name":"h","meaning":"一维 RNN 各时间步递推得到的状态","evidence":"最后状态到底混合了哪些历史"}]},{"id":"rnn-temporal-jacobian","section":4,"formulaIndex":1,"symbols":[{"name":"h","meaning":"较早或较晚时间步的隐藏状态","evidence":"hₖ 是较早第 k 步状态"},{"name":"t","meaning":"梯度路径终点的较晚时间步","evidence":"hₜ 是较晚第 t 步状态"},{"name":"k","meaning":"梯度路径起点的较早时间步","evidence":"第 k 步状态"},{"name":"i","meaning":"连乘中遍历的中间时间步","evidence":"乘积遍历中间时间步 i"},{"name":"diag","meaning":"把激活逐坐标导数组成对角矩阵","evidence":"激活函数逐坐标导数组成的对角矩阵"},{"name":"φ","meaning":"每个时间步使用的状态激活函数","evidence":"非线性饱和会进一步让 φ′ 接近零"},{"name":"W","meaning":"每个时间步复用的状态权重矩阵","evidence":"Wₕ 是每步复用的状态权重"}]},{"id":"rnn-lstm-state","section":5,"formulaIndex":1,"symbols":[{"name":"c","meaning":"LSTM 的旧、新细胞状态及候选内容","evidence":"cₜ₋₁、cₜ 是旧、新细胞状态"},{"name":"t","meaning":"当前 LSTM 时间步编号","evidence":"暴露给外部的隐藏状态"},{"name":"f","meaning":"控制旧细胞状态保留比例的遗忘门","evidence":"fₜ 是遗忘门"},{"name":"i","meaning":"控制候选内容写入比例的输入门","evidence":"iₜ 是输入门"},{"name":"h","meaning":"LSTM 暴露给外部的隐藏状态","evidence":"hₜ 是暴露给外部的隐藏状态"},{"name":"o","meaning":"控制细胞状态暴露比例的输出门","evidence":"oₜ 是输出门"},{"name":"tanh","meaning":"把细胞状态压缩后交给输出门的非线性","evidence":"完整非线性"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"RNN 在每个时间步复用同一递推单元更新隐藏状态。","evidence":"同一个单元在时间上反复使用"},"problem":{"answer":"它用固定大小状态处理可变长度、逐步到达的序列。","evidence":"参数量为何不随序列长度增加"},"inputOutput":{"answer":"输入 xt 和旧状态 ht−1，输出新状态 ht 与当前输出 yt。","evidence":"xₜ 是当前输入"},"mechanism":{"answer":"共享权重变换旧状态与当前输入，相加激活后再生成输出。","evidence":"序列变长只增加重复计算"},"interpretation":{"answer":"ht 是面向当前任务的历史摘要，不是可检索的完整日志。","evidence":"不是一份可检索的完整日志"},"boundary":{"answer":"共享递推允许任意长度，也会让同一误差和压缩反复累积。","evidence":"同一个变换及其误差反复作用"}},{"section":2,"definition":{"answer":"该例逐步计算一维线性 RNN 的三个隐藏状态。","evidence":"三步递推可以逐项手算"},"problem":{"answer":"它展示最终状态如何按时间距离加权混合历史输入。","evidence":"最后状态到底混合了哪些历史"},"inputOutput":{"answer":"输入 [1,0,2]、Wh=0.5 和 h0=0，输出 h3=2.25。","evidence":"h₃=0.5×0.5+2=2.25"},"mechanism":{"answer":"每一步把上一状态乘 0.5，再加当前输入。","evidence":"0.5×1+0"},"interpretation":{"answer":"最近输入权重一，两步前权重 0.25，说明早期影响衰减。","evidence":"两步前输入权重为 0.25"},"boundary":{"answer":"Wh 小于一导致遗忘，大于一可能放大状态并引发梯度爆炸。","evidence":"状态与梯度也更易爆炸"}},{"section":3,"definition":{"answer":"BPTT 把循环按时间展开，再沿展开图执行反向传播。","evidence":"时间展开把循环变成深度为 T 的计算图"},"problem":{"answer":"它把未来损失的责任分配给每次复用的递归参数。","evidence":"递归参数怎样收到来自未来损失的责任"},"inputOutput":{"answer":"输入保存的时间步激活和损失，输出共享参数各次贡献的总梯度。","evidence":"三次使用同一参数的梯度相加"},"mechanism":{"answer":"前向顺序递推，反向沿状态路径返回并累加复用贡献。","evidence":"梯度从未来沿共享状态路径返回"},"interpretation":{"answer":"序列越长，需保存的激活、反向路径和信用距离越长。","evidence":"序列越长，需保存的激活和梯度路径越长"},"boundary":{"answer":"截断 BPTT 省内存，但会切断超过 K 步的直接信用路径。","evidence":"超过 K 步的直接信用路径也被切断"}},{"section":4,"definition":{"answer":"时间梯度由每个中间步的激活导数和状态权重雅可比连续相乘。","evidence":"梯度问题来自雅可比反复相乘"},"problem":{"answer":"它解释 Wh=0.5 和 1.2 为何分别导致消失与爆炸。","evidence":"会走向两个极端"},"inputOutput":{"answer":"输入早晚状态、激活导数和 Wh，输出跨时间状态敏感度。","evidence":"hₜ 是较晚第 t 步状态"},"mechanism":{"answer":"按中间时间步顺序连乘 diag(φ′i)Wh。","evidence":"乘积遍历中间时间步 i"},"interpretation":{"answer":"十步 0.5 约 0.00098，十步 1.2 约 6.19。","evidence":"早期责任几乎消失"},"boundary":{"answer":"裁剪只限制爆炸，不能恢复已被状态丢弃的原文和长期记忆。","evidence":"被状态丢掉的原文"}},{"section":5,"definition":{"answer":"LSTM 用遗忘、输入和输出门控制加法细胞状态通道。","evidence":"用近似加法通道控制记忆"},"problem":{"answer":"它缓解普通 tanh RNN 长路径中每步完整非线性造成的衰减。","evidence":"更容易保留信息"},"inputOutput":{"answer":"输入旧状态、候选内容和三门，输出新 c 与暴露的 h。","evidence":"c̃ₜ 是候选内容"},"mechanism":{"answer":"遗忘门保留旧 c，输入门写候选，输出门决定暴露比例。","evidence":"决定旧记忆保留比例"},"interpretation":{"answer":"门是数据学习的连续向量，不是符号规则或硬存储槽。","evidence":"数据驱动的连续向量"},"boundary":{"answer":"即使 f=0.99，五百步后也只保留约 0.0066，不是无限记忆。","evidence":"0.99⁵⁰⁰≈0.0066"}},{"section":6,"definition":{"answer":"教师强制在训练时把真实上一步答案作为下一步输入。","evidence":"训练每一步都看真答案"},"problem":{"answer":"它造成训练与推理输入分布不同，单次错误上线后会滚雪球。","evidence":"教师强制制造训练—推理输入差异"},"inputOutput":{"answer":"训练输入真实 yt−1，推理输入模型预测，输出后续序列和状态。","evidence":"推理时只能输入模型自己的预测"},"mechanism":{"answer":"预测错误把状态带入训练中罕见区域，随后错误继续累积。","evidence":"后续错误继续累积"},"interpretation":{"answer":"这种分布错位称为 exposure bias，应单独评估自由生成轨迹。","evidence":"这叫 exposure bias"},"boundary":{"answer":"计划采样有偏，序列损失噪声大，解码策略也不修复训练错位。","evidence":"不修复训练分布错位"}},{"section":7,"definition":{"answer":"many-to-one、多对多、编码解码和双向是不同序列读取输出方式。","evidence":"双向、堆叠与多对多只是读取方式变化"},"problem":{"answer":"它为分类、逐步标注、生成和离线双向理解选择输出结构。","evidence":"分类、标注和生成各该取哪个输出"},"inputOutput":{"answer":"输入完整或流式序列，输出末状态、逐步标签或另一序列。","evidence":"many-to-one 取末状态"},"mechanism":{"answer":"双向模型分别读取左右文再合并，堆叠则把状态送入更深递推层。","evidence":"同时读取左右文"},"interpretation":{"answer":"双向利用已可见的未来上下文，不等于预测尚未到达的未来。","evidence":"双向不等于预测未来"},"boundary":{"answer":"严格在线场景不能使用双向未来输入，堆叠还会拉长优化路径。","evidence":"不能偷看尚未到达的数据"}},{"section":8,"definition":{"answer":"RNN 压缩历史到固定状态，注意力则保留各位置可直接访问的 KV。","evidence":"核心差别是访问历史的方式"},"problem":{"answer":"它比较小流式状态与精确回看全历史之间的成本收益。","evidence":"小状态和全量 KV 历史分别换来了什么"},"inputOutput":{"answer":"输入序列与部署约束，输出需实测的 RNN 或注意力方案。","evidence":"固定状态压缩"},"mechanism":{"answer":"RNN 顺序更新固定状态，注意力让当前位置直接连接旧位置。","evidence":"可直接连接旧位置"},"interpretation":{"answer":"低频传感器端侧可偏 RNN，引用远处原句的任务可偏注意力。","evidence":"在线异常检测"},"boundary":{"answer":"实际速度还取决于内核、批量和硬件，不能只按复杂度标签选型。","evidence":"实际速度取决于内核、批量和硬件"}},{"section":9,"definition":{"answer":"RNN 工程验收按依赖长度、流式状态和恢复场景拆分评测。","evidence":"评测要把长度、流式约束和状态恢复拆开"},"problem":{"answer":"它避免平均准确率掩盖长依赖遗忘和会话状态故障。","evidence":"平均准确率为何不能证明 RNN 真正记住长依赖"},"inputOutput":{"answer":"输入长度切片、干扰和恢复场景，输出性能曲线、延迟与状态指标。","evidence":"按依赖距离画性能曲线"},"mechanism":{"answer":"加入状态重置、缺包、超长外推，并测延迟、吞吐和冷启动。","evidence":"状态重置、缺包和超长外推"},"interpretation":{"answer":"随距离快速下降说明长依赖失败，跨用户串扰说明状态隔离错误。","evidence":"上下文串扰与隐私泄漏"},"boundary":{"answer":"隐藏状态须绑定身份、可重置并版本化，模型升级后旧状态可能不兼容。","evidence":"模型升级后旧状态未必兼容"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>手算一次 RNN 状态递推；从时间展开解释 BPTT；区分梯度爆炸与信息遗忘；理解 LSTM 门控和训练—推理错位。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>同一个单元在时间上反复使用<span class=\"dd-badge math\">核心递推</span></h2><p class=\"dd-lead\">参数量为何不随序列长度增加？</p><div class=\"dd-formula\">hₜ=φ(Wₕhₜ₋₁+Wₓxₜ+b)，　yₜ=g(Wᵧhₜ)</div><p><code>t</code> 是时间步，<code>xₜ</code> 是当前输入，<code>hₜ₋₁</code> 与 <code>hₜ</code> 是更新前后的隐藏状态；<code>Wₕ</code> 变换旧状态，<code>Wₓ</code> 变换当前输入，<code>b</code> 是偏置，<code>φ</code> 是状态激活；<code>Wᵧ</code> 和 <code>g</code> 把状态变成当前输出 <code>yₜ</code>。</p><p>所有时间步共享 Wₕ、Wₓ 和 b，所以序列变长只增加重复计算，不增加这组参数。hₜ 不是一份可检索的完整日志，而是模型为当前任务学到的历史摘要。共享参数让模型可处理任意长度，也让同一个变换及其误差反复作用。</p><div class=\"dd-note\"><b>贯穿例子：</b>用一维 RNN 读取三天设备信号 x=[1,0,2]，φ 暂取恒等函数，Wₕ=0.5、Wₓ=1、b=0、h₀=0。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>三步递推可以逐项手算<span class=\"dd-badge math\">算例</span></h2><p class=\"dd-lead\">最后状态到底混合了哪些历史？</p><p>沿用上一节的一维输入 x=[1,0,2]、Wₕ=0.5、Wₓ=1、b=0、h₀=0，并令激活为恒等函数。</p><div class=\"dd-formula\">h₁=1；　h₂=0.5；　h₃=0.5×0.5+2=2.25</div><p>展开 h₃ 可得 2+0.5×0+0.5²×1。最近输入权重为 1，两步前输入权重为 0.25；若 Wₕ=0.5，早期信息按距离指数衰减。若 Wₕ=1.2，影响可能增长，但状态与梯度也更易爆炸。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>t</th><th>xₜ</th><th>计算</th><th>hₜ</th></tr></thead><tbody><tr><td>1</td><td>1</td><td>0.5×0+1</td><td>1</td></tr><tr><td>2</td><td>0</td><td>0.5×1+0</td><td>0.5</td></tr><tr><td>3</td><td>2</td><td>0.5×0.5+2</td><td>2.25</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>时间展开把循环变成深度为 T 的计算图<span class=\"dd-badge math\">BPTT</span></h2><p class=\"dd-lead\">递归参数怎样收到来自未来损失的责任？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 730 265\" role=\"img\" aria-label=\"三步 RNN 时间展开与反向传播路径\"><defs><marker id=\"rnna\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#748093\"/></marker><marker id=\"rnnb\" markerWidth=\"8\" markerHeight=\"8\" refX=\"2\" refY=\"3\" orient=\"auto\"><path d=\"M6,0 L0,3 L6,6 z\" fill=\"#cf7d72\"/></marker></defs><text x=\"82\" y=\"38\" class=\"svg-t\">x₁=1</text><text x=\"302\" y=\"38\" class=\"svg-t\">x₂=0</text><text x=\"522\" y=\"38\" class=\"svg-t\">x₃=2</text><path d=\"M100,48 L100,92\" stroke=\"#748093\" marker-end=\"url(#rnna)\"/><path d=\"M320,48 L320,92\" stroke=\"#748093\" marker-end=\"url(#rnna)\"/><path d=\"M540,48 L540,92\" stroke=\"#748093\" marker-end=\"url(#rnna)\"/><rect x=\"42\" y=\"96\" width=\"116\" height=\"62\" rx=\"8\" fill=\"#21252d\" stroke=\"#65a6d9\"/><rect x=\"262\" y=\"96\" width=\"116\" height=\"62\" rx=\"8\" fill=\"#21252d\" stroke=\"#65a6d9\"/><rect x=\"482\" y=\"96\" width=\"116\" height=\"62\" rx=\"8\" fill=\"#21252d\" stroke=\"#65a6d9\"/><text x=\"100\" y=\"132\" text-anchor=\"middle\" class=\"svg-t\">h₁=1</text><text x=\"320\" y=\"132\" text-anchor=\"middle\" class=\"svg-t\">h₂=0.5</text><text x=\"540\" y=\"132\" text-anchor=\"middle\" class=\"svg-t\">h₃=2.25</text><path d=\"M158,127 L260,127\" stroke=\"#748093\" marker-end=\"url(#rnna)\"/><path d=\"M378,127 L480,127\" stroke=\"#748093\" marker-end=\"url(#rnna)\"/><path d=\"M540,158 L540,205\" stroke=\"#748093\" marker-end=\"url(#rnna)\"/><rect x=\"478\" y=\"207\" width=\"124\" height=\"42\" rx=\"8\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"540\" y=\"233\" text-anchor=\"middle\" class=\"svg-t\">损失 L₃</text><path d=\"M520,207 C440,185 405,183 350,158\" fill=\"none\" stroke=\"#cf7d72\" stroke-dasharray=\"6 4\" marker-end=\"url(#rnnb)\"/><path d=\"M490,216 C340,212 220,190 130,158\" fill=\"none\" stroke=\"#cf7d72\" stroke-dasharray=\"6 4\" marker-end=\"url(#rnnb)\"/><text x=\"252\" y=\"231\" class=\"svg-t\" font-size=\"11\">梯度从未来沿共享状态路径返回</text></svg><figcaption>图 1　前向是顺序递推；BPTT 将三次使用同一参数的梯度相加。序列越长，需保存的激活和梯度路径越长。</figcaption></figure><p>反向传播穿过展开图并累加每次参数复用的贡献。截断 BPTT 每 K 步切断图，内存从依赖整段变为依赖 K，但超过 K 步的直接信用路径也被切断。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>梯度问题来自雅可比反复相乘<span class=\"dd-badge math\">长依赖</span></h2><p class=\"dd-lead\">为什么 Wₕ=0.5 与 1.2 会走向两个极端？</p><div class=\"dd-formula\">∂hₜ/∂hₖ = ∏<sub>i=k+1…t</sub> diag(φ′ᵢ)Wₕ</div><p><code>hₖ</code> 是较早第 k 步状态，<code>hₜ</code> 是较晚第 t 步状态；乘积遍历中间时间步 i，<code>diag(φ′ᵢ)</code> 是激活函数逐坐标导数组成的对角矩阵，<code>Wₕ</code> 是每步复用的状态权重。在一维线性例子中，跨 d 步梯度就是 Wₕᵈ：0.5¹⁰≈0.00098，早期责任几乎消失；1.2¹⁰≈6.19，容易爆炸。非线性饱和会进一步让 φ′ 接近零。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>现象</th><th>表现</th><th>常用缓解</th><th>不能解决</th></tr></thead><tbody><tr><td>梯度爆炸</td><td>loss/范数突增、NaN</td><td>梯度裁剪、初始化、归一化</td><td>长期记忆容量</td></tr><tr><td>梯度消失</td><td>早期 token 学不到责任</td><td>门控、残差、较短路径</td><td>被状态丢掉的原文</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>LSTM 用近似加法通道控制记忆<span class=\"dd-badge math\">门控</span></h2><p class=\"dd-lead\">门控为何比普通 tanh RNN 更容易保留信息？</p><div class=\"dd-formula\">cₜ=fₜ⊙cₜ₋₁+iₜ⊙c̃ₜ，　hₜ=oₜ⊙tanh(cₜ)</div><p><code>cₜ₋₁、cₜ</code> 是旧、新细胞状态，<code>c̃ₜ</code> 是候选内容；<code>fₜ</code> 是遗忘门，<code>iₜ</code> 是输入门，<code>oₜ</code> 是输出门，<code>⊙</code> 表示逐元素乘法，<code>hₜ</code> 是暴露给外部的隐藏状态。</p><p>遗忘门 f 决定旧记忆保留比例，输入门 i 决定写入多少候选，输出门 o 决定暴露多少状态。若 f≈1、i≈0，c 可沿近似恒等路径传递，梯度不必每步都穿过完整非线性。GRU 合并状态与部分门，参数更少。</p><p>门不是符号规则或硬存储槽；它们是数据驱动的连续向量。即使 f=0.99，跨 500 步保留比例也只有 0.99⁵⁰⁰≈0.0066。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>教师强制制造训练—推理输入差异<span class=\"dd-badge eng\">生成</span></h2><p class=\"dd-lead\">训练每一步都看真答案，为什么上线会滚雪球？</p><p>训练序列生成器时，常把真实 yₜ₋₁ 输入下一步；推理时只能输入模型自己的预测。一处错误把状态带到训练中很少见的区域，后续错误继续累积，这叫 exposure bias。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>方法</th><th>作用</th><th>代价/边界</th></tr></thead><tbody><tr><td>计划采样</td><td>逐步混入模型预测</td><td>目标有偏、调度敏感</td></tr><tr><td>序列级损失</td><td>直接优化最终指标</td><td>梯度估计噪声大</td></tr><tr><td>beam/约束解码</td><td>推理时减少局部错误</td><td>不修复训练分布错位</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>双向、堆叠与多对多只是读取方式变化<span class=\"dd-badge intuition\">变体</span></h2><p class=\"dd-lead\">分类、标注和生成各该取哪个输出？</p><p>many-to-one 取末状态做序列分类；many-to-many 为每步输出标签；编码器—解码器把输入压为状态再生成另一序列。双向 RNN 同时读取左右文，适合离线标注，却不能用于严格在线的未来未知场景。堆叠层提升容量，也拉长优化路径。</p><div class=\"dd-note warn\"><b>双向不等于预测未来。</b>它只适用于推理时完整序列已可见的任务；实时传感器不能偷看尚未到达的数据。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>RNN 与注意力的核心差别是访问历史的方式<span class=\"dd-badge eng\">选型</span></h2><p class=\"dd-lead\">小状态和全量 KV 历史分别换来了什么？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>维度</th><th>RNN</th><th>自注意力/Transformer</th></tr></thead><tbody><tr><td>历史表示</td><td>固定状态压缩</td><td>保留各位置 KV</td></tr><tr><td>训练并行</td><td>时间依赖强</td><td>位置可并行</td></tr><tr><td>单步流式状态</td><td>固定大小</td><td>KV 随长度增长</td></tr><tr><td>精确回看</td><td>困难</td><td>可直接连接旧位置</td></tr><tr><td>典型优势</td><td>端侧、传感器、低延迟</td><td>大规模训练、长程交互</td></tr></tbody></table></div><p>实际速度取决于内核、批量和硬件。对每秒一个传感器值的在线异常检测，小 GRU 可能比大型 Transformer 更合适；对需要引用数千 token 之前原句的任务则相反。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>评测要把长度、流式约束和状态恢复拆开<span class=\"dd-badge eng\">工程边界</span></h2><p class=\"dd-lead\">平均准确率为何不能证明 RNN 真正记住长依赖？</p><p>按依赖距离画性能曲线，并加入干扰项、状态重置、缺包和超长外推。部署时测每步延迟、状态大小、批处理吞吐、冷启动和断线恢复；若把隐藏状态跨用户复用，会造成上下文串扰与隐私泄漏。</p><div class=\"dd-note warn\"><b>隐藏状态属于会话状态。</b>应绑定身份、设置生命周期、可重置并版本化；模型升级后旧状态未必兼容。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">10</span>常见误区与学习路线<span class=\"dd-badge intuition\">误区与依赖</span></h2><p class=\"dd-lead\">把“循环”理解成计算图共享，而不是无限记忆。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>隐藏状态保存全部历史</td><td>它是固定容量的任务相关压缩</td></tr><tr><td>裁剪梯度能解决消失</td><td>它主要限制爆炸</td></tr><tr><td>LSTM 可以无限记忆</td><td>门控改善路径但仍会衰减和覆盖</td></tr><tr><td>双向 RNN 可用于实时预测</td><td>它需要完整未来上下文</td></tr><tr><td>Transformer 让 RNN 完全过时</td><td>流式小状态场景仍有优势</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>依赖与延伸</th></tr></thead><tbody><tr><td>先修</td><td>神经网络、反向传播、梯度消失</td></tr><tr><td><b>本页核心</b></td><td>递推状态、BPTT、门控、教师强制</td></tr><tr><td>对比</td><td>Transformer、状态空间模型、注意力</td></tr><tr><td>应用</td><td>语音、时间序列、流式推理</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">11</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>序列逐步到达</li><li>共享递推更新隐藏状态</li><li>时间展开形成深计算图</li><li>BPTT 沿状态路径分配责任</li><li>门控选择保留与写入</li><li>以长度和流式约束验收</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">12</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>例子中 h₃ 为什么等于2.25？</li><li>Wₕ=0.5 时跨10步梯度约多少？</li><li>截断 BPTT 的主要代价是什么？</li><li>梯度裁剪主要缓解什么？</li><li>双向 RNN 何时不适用？</li><li>假设“循环神经网络 RNN：把历史压进一个不断更新的状态”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li><li>如何为“循环神经网络 RNN：把历史压进一个不断更新的状态”设计一个最小对照实验，证明观察到的改善来自核心机制，而不是数据、提示、权限或评测口径同时变化？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>h₃=0.5h₂+x₃=0.5×0.5+2=2.25。</li><li>0.5¹⁰≈0.00098，表现为梯度消失。</li><li>超过截断窗口的直接信用分配路径被切断。</li><li>限制梯度爆炸；不能恢复已经消失的长期信号。</li><li>严格在线、未来输入尚不可见的实时场景。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li><li>固定数据、模型版本、提示、权限、预算和评测，只改变一个与核心机制直接相关的因素，并在多个样本与随机种子上重复；同时保存中间状态和失败样本。若差异只在目标因素变化时稳定出现，才支持机制解释，否则应继续排查混杂变量。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://ieeexplore.ieee.org/document/279181\" target=\"_blank\" rel=\"noopener\">Learning Long-Term Dependencies with Gradient Descent is Difficult</a>：长依赖梯度困难</li><li><a href=\"https://www.bioinf.jku.at/publications/older/2604.pdf\" target=\"_blank\" rel=\"noopener\">Long Short-Term Memory</a>：LSTM 门控记忆</li><li><a href=\"https://arxiv.org/abs/1406.1078\" target=\"_blank\" rel=\"noopener\">Learning Phrase Representations using RNN Encoder–Decoder</a>：GRU 与编码器—解码器</li><li><a href=\"https://arxiv.org/abs/1506.03099\" target=\"_blank\" rel=\"noopener\">Scheduled Sampling for Sequence Prediction with Recurrent Neural Networks</a>：训练—推理错位</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
